using namespace std;

struct Edge {
    int dist2;
    uint16_t from, to;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> x(N), y(N);
    for (int i = 0; i < N; ++i) {
        cin >> x[i] >> y[i];
    }

    vector<Edge> edges;
    edges.reserve(static_cast<size_t>(N) * (N - 1) + N);

    for (int i = 0; i < N; ++i) {
        edges.push_back({x[i] * x[i] + y[i] * y[i],
                         static_cast<uint16_t>(N),
                         static_cast<uint16_t>(i)});
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (i == j) continue;
            int dx = x[i] - x[j];
            int dy = y[i] - y[j];
            edges.push_back({dx * dx + dy * dy,
                             static_cast<uint16_t>(i),
                             static_cast<uint16_t>(j)});
        }
    }

    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
        return a.dist2 > b.dist2;
    });

    vector<int> best(N + 1, 0);
    vector<int> pending(N + 1, 0);
    vector<int> touched;
    best[N] = 0;

    for (size_t i = 0; i < edges.size();) {
        size_t j = i;
        while (j < edges.size() && edges[j].dist2 == edges[i].dist2) {
            const Edge& e = edges[j];
            int candidate = best[e.from] + 1;
            if (candidate > pending[e.to]) {
                if (pending[e.to] == 0) touched.push_back(e.to);
                pending[e.to] = candidate;
            }
            ++j;
        }

        for (int v : touched) {
            best[v] = max(best[v], pending[v]);
            pending[v] = 0;
        }
        touched.clear();
        i = j;
    }

    cout << *max_element(best.begin(), best.begin() + N) << '\n';
    return 0;
}
